package net.civeira.phylax.features.access.clientidentity.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.access.clientidentity.domain.ClientIdentity;
import net.civeira.phylax.features.access.clientidentity.domain.event.ClientIdentityEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ClientIdentityEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ClientIdentityEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ClientIdentity entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
